import React, { useState, useRef } from 'react';
import { Layout, Menu, Dropdown, Button, List, Badge, Card, Input, Select, Row, Col } from 'antd';
import {
    HomeOutlined,
    CameraOutlined,
    VideoCameraOutlined,
    FullscreenOutlined,
    SearchOutlined,
    WarningOutlined,
} from '@ant-design/icons';
import ReactPlayer from 'react-player';
import './Monitor.css'; // 自定义样式
import html2canvas from 'html2canvas';
import AfterVideo from '../assets/识别后.mp4';

const { Header, Content, Sider } = Layout;

const Monitor = () => {
    const [isRecording, setIsRecording] = useState(false); // 录像状态
    const [mediaRecorder, setMediaRecorder] = useState(null); // MediaRecorder 实例
    const [isFullScreen, setIsFullScreen] = useState(false); // 全屏状态
    const [isDetectionOn, setIsDetectionOn] = useState(true); // AI 检测开关
    const [selectedCamera, setSelectedCamera] = useState('监控列表'); // 当前摄像头
    const [searchQuery, setSearchQuery] = useState(''); // 搜索关键词

    const playerRef = useRef(null); // 用于获取 ReactPlayer 实例

    // 录屏功能实现
    const handleRecord = () => {
        if (!isRecording) {
            // 开始录像
            const videoElement = playerRef.current.getInternalPlayer(); // 获取内部的 <video> 元素
            if (videoElement && videoElement.srcObject) {
                const stream = videoElement.srcObject;
                const recorder = new MediaRecorder(stream);
                const chunks = [];

                recorder.ondataavailable = (e) => chunks.push(e.data);
                recorder.onstop = () => {
                    const blob = new Blob(chunks, { type: 'video/mp4' });
                    const link = document.createElement('a');
                    link.download = 'recording.mp4'; // 下载文件名
                    link.href = URL.createObjectURL(blob); // 转换为视频 URL
                    link.click(); // 触发下载
                };

                recorder.start();
                setMediaRecorder(recorder);
                setIsRecording(true);
            } else {
                console.error('无法获取视频流');
            }
        } else {
            // 停止录像
            if (mediaRecorder) {
                mediaRecorder.stop();
                setIsRecording(false);
            }
        }
    };

    // 截图功能实现
    const handleScreenshot = () => {
        const videoElement = document.querySelector('.video-container'); // 获取视频容器
        if (videoElement) {
            html2canvas(videoElement).then((canvas) => {
                const link = document.createElement('a');
                link.download = 'screenshot.png'; // 下载文件名
                link.href = canvas.toDataURL(); // 转换为图片 URL
                link.click(); // 触发下载
            });
        }
    };
    const toggleFullScreen = () => {
        const videoContainer = document.querySelector('.video-container');
        if (videoContainer) {
            if (!document.fullscreenElement) {
                videoContainer.requestFullscreen(); // 进入全屏
            } else {
                document.exitFullscreen(); // 退出全屏
            }
        }
    };

// 修改按钮代码
    <Button icon={<FullscreenOutlined />} onClick={toggleFullScreen} className="blue-button">
        全屏
    </Button>

    // 模拟摄像头列表
    const cameras = ['长安校区星天苑D座外监控', '友谊校区诚字楼一楼外监控', '长安校区图书馆正门外', '长安校区小东门外监控'];

    // 模拟车辆检测记录
    const vehicleRecords = [
        { id: 1, type: '小汽车', time: '2023-10-01 12:30', confidence: '95%', isAbnormal: false },
        { id: 2, type: '货车', time: '2023-10-01 12:35', confidence: '90%', isAbnormal: true },
        { id: 3, type: '危险品车', time: '2023-10-01 12:40', confidence: '98%', isAbnormal: true },
    ];

    // 模拟异常警报
    const alerts = [
        { id: 1, type: '禁行车辆进入', vehicle: '危险品车', time: '2023-10-01 12:40', status: '待处理' },
        { id: 2, type: '车辆超速', vehicle: '小汽车', time: '2023-10-01 12:45', status: '已确认' },
    ];

    // 切换摄像头
    const handleCameraChange = (camera) => {
        setSelectedCamera(camera);
    };

    //

    // 切换 AI 检测
    const toggleDetection = () => {
        setIsDetectionOn(!isDetectionOn);
    };

    // 过滤车辆检测记录
    const filteredRecords = vehicleRecords.filter((record) =>
        record.type.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <Layout className="monitor-layout">
            {/* 顶部导航栏 */}
            <Header className="header">
                <div className="left-actions">
                    <Button icon={<HomeOutlined />} onClick={() => window.location.href = '/'} className="blue-button">
                        返回主页
                    </Button>
                    <Dropdown
                        menu={{
                            items: cameras.map((camera) => ({
                                key: camera,
                                label: camera,
                                onClick: () => handleCameraChange(camera),
                            })),
                        }}
                    >
                        <Button className="blue-button">
                            {selectedCamera} <VideoCameraOutlined />
                        </Button>
                    </Dropdown>
                    <Button icon={<CameraOutlined />} className="blue-button" onClick={handleScreenshot}>
                        截图
                    </Button>
                    <Button icon={<VideoCameraOutlined />} className="blue-button" onClick={handleRecord}>
                        {isRecording ? '停止录像' : '录像'}
                    </Button>
                    <Button onClick={toggleDetection} className="blue-button">
                        AI 检测 {isDetectionOn ? '开启' : '关闭'}
                    </Button>
                    <Button icon={<FullscreenOutlined />} onClick={toggleFullScreen} className="blue-button">
                        全屏
                    </Button>
                </div>
            </Header>

            {/* 主要内容区域 */}
            <Layout>
                {/* 实时视频流 */}
                <Content className="video-content">
                    <Row gutter={[16, 16]}>
                        <Col span={18}>
                            <Card className="video-card">
                                <div className={`video-container ${isFullScreen ? 'fullscreen' : ''}`}>
                                    <ReactPlayer
                                        ref={playerRef} // 绑定 ref
                                        url={AfterVideo} // 使用 public 目录下的文件
                                        playing
                                        controls
                                        width="100%"
                                        height="100%"
                                    />
                                    {isDetectionOn && (
                                        <div className="detection-overlay">
                                            {/* 模拟检测框 */}
                                            <div className="detection-box" style={{ top: '20%', left: '30%', borderColor: 'blue' }}>
                                                小汽车 95%
                                            </div>
                                            <div className="detection-box" style={{ top: '40%', left: '50%', borderColor: 'red' }}>
                                                危险品车 98%
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </Card>
                        </Col>
                        <Col span={6}>
                            <Card title="异常警报" className="alert-card">
                                <List
                                    dataSource={alerts}
                                    renderItem={(alert) => (
                                        <List.Item>
                                            <List.Item.Meta
                                                title={alert.type}
                                                description={`${alert.vehicle} | ${alert.time}`}
                                            />
                                            <Badge
                                                status={alert.status === '待处理' ? 'error' : 'success'}
                                                text={alert.status}
                                            />
                                        </List.Item>
                                    )}
                                />
                            </Card>
                        </Col>
                    </Row>
                </Content>

                {/* 侧边栏：车辆检测记录 */}
                <Sider width={300} className="sidebar">
                    <div className="search-bar">
                        <Input
                            placeholder="搜索车辆类型"
                            prefix={<SearchOutlined />}
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                    <List
                        dataSource={filteredRecords}
                        renderItem={(record) => (
                            <List.Item>
                                <Badge
                                    status={record.isAbnormal ? 'error' : 'success'}
                                    text={`${record.type} | ${record.time} | ${record.confidence}`}
                                />
                            </List.Item>
                        )}
                    />
                </Sider>
            </Layout>
        </Layout>
    );
};

export default Monitor;