import React, { useState } from 'react';
import { Layout, Card, Button, Row, Col, List, DatePicker, Select } from 'antd';
import { DownloadOutlined } from '@ant-design/icons';
import moment from 'moment'; // 引入 moment 库
import './History.css'; // 自定义样式

const { Header, Content } = Layout;
const { RangePicker } = DatePicker;
const { Option } = Select;

const History = () => {
    const [selectedDate, setSelectedDate] = useState(moment('2025-03-06')); // 使用 moment 对象
    const [selectedRange, setSelectedRange] = useState([
        moment('2024-02-14'),
        moment('2024-02-28'),
    ]); // 使用 moment 对象

    // 模拟数据
    const vehicleStats = [
        { type: 'bus', count: 15 },
        { type: 'van', count: 352 },
        { type: 'truck', count: 85 },
        { type: 'car', count: 3250 },
    ];

    const anomalies = [
        '1月2日上午12点30分15秒 一辆重卡进入长安校区……',
        '1月3日下午3点45分20秒 一辆货车超速……',
        '1月4日晚上8点15分10秒 一辆小汽车违规停车……',
    ];

    // 处理日期选择
    const handleDateChange = (date) => {
        setSelectedDate(date);
    };

    // 处理日期范围选择
    const handleRangeChange = (dates) => {
        setSelectedRange(dates);
    };

    // 处理数据导出
    const handleExport = () => {
        // 这里可以添加导出逻辑
    };

    return (
        <Layout className="history-layout">


            {/* 主要内容区域 */}
            <Content className="content">
                <Row gutter={[16, 16]}>
                    {/* 左列卡片列表 */}
                    <Col span={12}>
                        {/* 卡片 1：2025.3.6日各类型车辆数量和异常统计 */}
                        <Card title="2025.3.6日各类型车辆数量和异常统计" className="data-card">
                            <Row gutter={[16, 16]}>
                                <Col span={12}>
                                    <DatePicker
                                        defaultValue={selectedDate}
                                        onChange={handleDateChange}
                                        picker="date"
                                        style={{ width: '100%' }}
                                    >
                                        <Button
                                            type="primary"
                                            style={{
                                                fontWeight: 'bold',
                                                color: 'blue',
                                                height: 50,
                                                fontSize: '16px',
                                                padding: '0 20px',
                                            }}
                                        >
                                            选择日期
                                        </Button>
                                    </DatePicker>
                                </Col>
                                <Col span={12} style={{ textAlign: 'right' }}>
                                    {selectedDate.format('YYYY-MM-DD')} {/* 显示当前选择的日期 */}
                                </Col>
                            </Row>
                            <List
                                dataSource={vehicleStats}
                                renderItem={(item) => (
                                    <List.Item>
                                        <span>{item.type}数量统计</span>
                                        <span>{item.count}辆</span>
                                    </List.Item>
                                )}
                            />
                        </Card>

                        {/* 卡片 2：异常记录 */}
                        <Card className="data-card">
                            <List
                                dataSource={anomalies}
                                renderItem={(item) => (
                                    <List.Item style={{ color: 'red' }}>{item}</List.Item>
                                )}
                            />
                        </Card>
                    </Col>

                    {/* 右列卡片列表 */}
                    <Col span={12}>
                        {/* 卡片 1：2024.2.14到2024.2.28的车辆流量统计 */}
                        <Card title="2024.2.14到2024.2.28的车辆流量统计" className="data-card">
                            <RangePicker
                                defaultValue={selectedRange} // 使用 moment 对象
                                onChange={handleRangeChange}
                            />
                            <div style={{ height: 300, marginTop: 16 }}>
                                {/* 折线图占位 */}
                                折线图（bus、van、truck、car）
                            </div>
                        </Card>

                        {/* 卡片 2：导入数据和饼图 */}
                        <Card className="data-card">
                            <Row gutter={[16, 16]}>
                                <Col span={12}>
                                    <span>导入2024.2.14到2024.2.28的车辆流量统计数据为：</span>
                                    <Select defaultValue="csv" style={{ width: 120, marginLeft: 8 }}>
                                        <Option value="csv">CSV</Option>
                                        <Option value="excel">Excel</Option>
                                    </Select>
                                    <Button icon={<DownloadOutlined />} style={{ marginLeft: 8 }} onClick={handleExport}>
                                        导出
                                    </Button>
                                </Col>
                                <Col span={12} style={{ textAlign: 'right' }}>
                                    <span>车辆类型占比饼图</span>
                                    <div style={{ height: 200, marginTop: 16 }}>
                                        {/* 饼图占位 */}
                                        饼图
                                    </div>
                                </Col>
                            </Row>
                        </Card>
                    </Col>
                </Row>
            </Content>
        </Layout>
    );
};

export default History;